class Solution {
public:
    int longestSemiRepeatingSubarray(vector<int>& nums, int k) {
        unordered_map<int,int> cnt;
        int rep = 0, l = 0, ans = 0;
        for (int r = 0; r < (int)nums.size(); r++) {
            if (++cnt[nums[r]] == 2) rep++;
            while (rep > k) {
                if (--cnt[nums[l]] == 1) rep--;
                l++;
            }
            ans = max(ans, r - l + 1);
        }
        return ans;
    }
};

