class Solution {
    public int longestSemiRepeatingSubarray(int[] nums, int k) {
        Map<Integer,Integer> cnt = new HashMap<>();
        int rep = 0, l = 0, ans = 0;
        for (int r = 0; r < nums.length; r++) {
            cnt.merge(nums[r], 1, Integer::sum);
            if (cnt.get(nums[r]) == 2) rep++;
            while (rep > k) {
                int c = cnt.merge(nums[l], -1, Integer::sum);
                if (c == 1) rep--;
                l++;
            }
            ans = Math.max(ans, r - l + 1);
        }
        return ans;
    }
}

