class Solution {
    bool ok(vector<int>& nums, int L, int k) {
        unordered_map<int,int> c;
        int rep = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (++c[nums[i]] == 2) rep++;
            if (i >= L && --c[nums[i - L]] == 1) rep--;
            if (i >= L - 1 && rep <= k) return true;
        }
        return false;
    }
public:
    int longestSemiRepeatingSubarray(vector<int>& nums, int k) {
        int lo = 1, hi = nums.size(), ans = 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(nums, mid, k)) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }
};

